import{z as l,x as p,o as e,c as A,q as s,j as i,D as t,d as r,s as B,S as n,b as o}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"序列化：JSON / Protobuf","description":"","frontmatter":{"title":"序列化：JSON / Protobuf","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/serialization-protobuf.md","filePath":"cs/serialization-protobuf.md","lastUpdated":1791063341000}'),d={name:"cs/serialization-protobuf.md"};function f(u,a,P,b,c,h){const E=p("Mermaid");return e(),A("div",null,[a[2]||(a[2]=s('<h1 id="序列化-json-protobuf" tabindex="-1">序列化：JSON / Protobuf <a class="header-anchor" href="#序列化-json-protobuf" aria-label="Permalink to &quot;序列化：JSON / Protobuf&quot;">​</a></h1><div class="epigraph"><p>JSON 是自描述文本，便于调试与浏览器；Protobuf 是带 schema 的二进制，省带宽与 CPU。都是应用编码，不是 HTTP。</p><footer>—— 据 RFC 8259 JSON；Protobuf 语言指南整理</footer></div><p><a href="/cs/rest-grpc">上一课</a> 假定有一种编码。<a href="/cs/content-negotiation">内容协商</a> 可选 <code>application/json</code>。缺口是<strong>编码本身</strong>：字段、版本、与报文成帧。本课结束 HTTP 与 Web 协议课序。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>进程内存结构不能直接上<a href="/cs/socket-api">套接字</a>。JSON：Unicode 文本、对象图、无原生二进制（用 base64）。Protobuf：字段号、varint、向前兼容靠未识别字段保留。gRPC 默认后者。压缩可再叠 gzip，但 Protobuf 已密，收益小。schema 演化：加可选字段易，改语义难——与 DB 模式后课不同栏，这里只钉报文。</p><p>不要把 Protobuf 写成加密。</p><p><span class="marginnote">RFC 8259。Protobuf 是 Google 开文档的 IDL。本课不把每种 IDL（Thrift/Avro）列完。</span></p><p><span class="marginnote">数字实例：varint 把整数按 7 位一段编码，每段最高位当「还有下一字节」的旗子。数字 300 = 二进制 100101100，拆成 10 与 44，线上写成两个字节——小整数通常只占 1 字节，这是它比定长 4 字节 int 省带宽的原因。</span></p><h3 id="编码不等于成帧" tabindex="-1">编码不等于成帧 <a class="header-anchor" href="#编码不等于成帧" aria-label="Permalink to &quot;编码不等于成帧&quot;">​</a></h3><p>JSON 自描述；Protobuf 靠字段号。无长度前缀仍会粘包。schema 演化属于合同。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：可读 vs 紧凑；有无 schema。画：结构 → 字节 → 解析。与线路码对照：一层在 PHY，一层在应用。粘包后课：Protobuf 消息仍要长度前缀或 gRPC 帧。</p>',12)),(e(),i(n,null,{default:t(()=>[B(E,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20OBJ%5B%22%E5%86%85%E5%AD%98%E5%AF%B9%E8%B1%A1%22%5D%20--%3E%20JSON%5B%22%E8%87%AA%E6%8F%8F%E8%BF%B0%E6%96%87%E6%9C%AC%22%5D%0A%20%20OBJ%20--%3E%20PB%5B%22%E5%AD%97%E6%AE%B5%E5%8F%B7%E4%BA%8C%E8%BF%9B%E5%88%B6%22%5D%0A%20%20PB%20--%3E%20WIRE%5B%22%E5%86%8D%E8%BF%9B%20HTTP%2FgRPC%20%E5%B8%A7%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o("h2",{id:"机制",tabindex:"-1"},[r("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=o("p",null,"CPU：JSON 解析在 10G 上可成瓶颈，TSO 帮不上。QUIC 0-RTT 重放对非幂等 POST+JSON 危险。CDN 可缓存 GET+JSON，难缓存 gRPC。IPv6 过渡不影响编码。",-1)),a[5]||(a[5]=o("p",null,"安全：JSON 炸弹、Protobuf 递归深度是解析器边界。",-1)),a[6]||(a[6]=o("p",null,"上面那张图画的是「对象怎么变成字节」；下面这张回答「加了新字段，旧服务为什么还能解析」——向前兼容就发生在字段号对不上的那一刻。",-1)),(e(),i(n,null,{default:t(()=>[B(E,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E8%AF%BB%E5%88%B0%E5%AD%97%E6%AE%B5%E5%A4%B4%3A%20%E5%AD%97%E6%AE%B5%E5%8F%B7%2B%E7%B1%BB%E5%9E%8B%22%5D%20--%3E%20B%7B%22%E6%97%A7%20reader%20%E8%AE%A4%E8%AF%86%E6%AD%A4%E5%AD%97%E6%AE%B5%E5%8F%B7%3F%22%7D%0A%20%20B%20--%20%22%E8%AE%A4%E8%AF%86%22%20--%3E%20C%5B%22%E6%8C%89%E7%B1%BB%E5%9E%8B%E8%AF%BB%E5%80%BC%E5%A1%AB%E8%BF%9B%E7%BB%93%E6%9E%84%22%5D%0A%20%20B%20--%20%22%E4%B8%8D%E8%AE%A4%E8%AF%86%22%20--%3E%20D%5B%22%E6%8C%89%E9%95%BF%E5%BA%A6%E8%B7%B3%E8%BF%87%20%E5%B9%B6%E4%BF%9D%E7%95%99%E5%8E%9F%E5%A7%8B%E5%AD%97%E8%8A%82%22%5D%0A%20%20D%20--%3E%20E%5B%22%E5%86%99%E5%9B%9E%E6%97%B6%E5%8E%9F%E6%A0%B7%E5%B8%A6%E4%B8%8A%22%5D%0A%20%20C%20--%3E%20F%5B%22%E7%BB%A7%E7%BB%AD%E4%B8%8B%E4%B8%80%E6%AE%B5%20%E7%9B%B4%E5%88%B0%E6%B6%88%E6%81%AF%E7%BB%93%E6%9D%9F%22%5D%0A%20%20E%20--%3E%20F%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=s('<p><span class="marginnote">常见误区：把「能解析」当「安全」。几 KB 的 JSON 可以展开成上 GB 的嵌套对象（JSON 炸弹），Protobuf 也有递归深度限制——解析器必须设深度与大小上限，否则一个恶意报文就能吃光内存。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 ASN.1 的全部。DNS 缓存与 TTL 是下一课序第一课。后课默认：JSON 易互通；Protobuf 要 schema 与帧。</p><p>无长度的 JSON 流会粘包，不能只靠 TCP。</p><p><span class="marginnote">术语翻译：「字段号」是 Protobuf 给每个字段编的整数编号，线上传的是编号不是字段名——所以改名不影响编码；但改编号等于换了一个新字段，旧读者会把新数据当「不认识的字段」跳过，数据悄悄丢失。</span></p><p>下一课<a href="/cs/dns-cache-ttl">DNS 缓存与 TTL</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>JSON 自描述；Protobuf 靠字段号与 schema。</li><li>编码不等于运输，还要成帧。</li><li>演化规则属于合同，不是语法边角。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 8259；Protobuf 文档。</li></ul>',8))])}const S=l(d,[["render",f]]);export{D as __pageData,S as default};
